class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        if n <= 1:
            return n

        max_length = 1
        start = 0
        consecutive_pairs = 0

        for end in range(1, n):
            if s[end] == s[end - 1]:
                consecutive_pairs += 1

            while consecutive_pairs > 1:
                if s[start] == s[start + 1]:
                    consecutive_pairs -= 1
                start += 1

            max_length = max(max_length, end - start + 1)

        return max_length

